import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.RycU2wFZ.js";const c=JSON.parse('{"title":"超时不等于失败","description":"为什么网络超时后不能直接重试付款，以及 AgentPay 如何避免重复扣款","frontmatter":{"title":"超时不等于失败","description":"为什么网络超时后不能直接重试付款，以及 AgentPay 如何避免重复扣款"},"headers":[],"relativePath":"zh/learn/04-agentpay-concepts/timeout-is-not-failure.md","filePath":"zh/learn/04-agentpay-concepts/timeout-is-not-failure.md","lastUpdated":1792490239000}'),e={name:"zh/learn/04-agentpay-concepts/timeout-is-not-failure.md"};function p(l,s,h,o,r,d){return t(),n("div",null,[...s[0]||(s[0]=[i(`<h1 id="超时不等于失败" tabindex="-1">超时不等于失败 <a class="header-anchor" href="#超时不等于失败" aria-label="Permalink to &quot;超时不等于失败&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">实验性项目</p><p>AgentPay 尚未经过独立安全审计，请勿用于生产环境的真实资金。本页示例均基于测试网和测试代币。</p></div><h2 id="一句话结论" tabindex="-1">一句话结论 <a class="header-anchor" href="#一句话结论" aria-label="Permalink to &quot;一句话结论&quot;">​</a></h2><p><strong>超时只说明&quot;你没有收到结果&quot;，不说明&quot;事情没有发生&quot;。</strong> 在涉及资金的系统里，遇到超时必须先查清楚发生了什么，而不是直接重试。</p><h2 id="一个具体的故事" tabindex="-1">一个具体的故事 <a class="header-anchor" href="#一个具体的故事" aria-label="Permalink to &quot;一个具体的故事&quot;">​</a></h2><p>还是那个调研 Agent。这次它调用一个行情接口，价格 0.1 USDC（<code>100_000</code> 个最小单位）。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Agent 请求接口           → 收到&quot;需要付款&quot;的要求</span></span>
<span class="line"><span>2. Agent 签名授权并重新请求   → 付款已提交</span></span>
<span class="line"><span>3. 链上扣款成功             ✅</span></span>
<span class="line"><span>4. 卖方的服务处理完毕，准备返回数据</span></span>
<span class="line"><span>5. 响应在网络中丢失 / 卖方响应超时   ⏱️</span></span>
<span class="line"><span>6. Agent 收到超时错误</span></span></code></pre></div><p>Agent 看到的只是一个超时。它的重试逻辑认为&quot;没成功，再来一次&quot;：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>7. Agent 再次请求，再次付款</span></span>
<span class="line"><span>8. 第二笔也成功             ✅</span></span></code></pre></div><p>结果：<strong>付了两次钱，其中一次对应的服务其实已经交付过了。</strong> 这就是重复扣款（Double Charge）。</p><p>问题的根源是一个错误的等式：</p><blockquote><p>❌ 超时 = 失败 → 可以重试</p></blockquote><h2 id="为什么会这样" tabindex="-1">为什么会这样 <a class="header-anchor" href="#为什么会这样" aria-label="Permalink to &quot;为什么会这样&quot;">​</a></h2><p>一次付款至少涉及三件相互独立的事情：</p><table tabindex="0"><thead><tr><th>环节</th><th>回答的问题</th></tr></thead><tbody><tr><td><strong>付款意图</strong></td><td>这笔付款请求本身是否被接受、是否在有效期内</td></tr><tr><td><strong>资金结算</strong></td><td>钱是否真的划转了（链上交易，或平台钱包扣费）</td></tr><tr><td><strong>服务交付</strong></td><td>卖方的上游服务是否真的执行并返回了结果</td></tr></tbody></table><p>它们发生在不同的系统里，状态各自推进。超时可能发生在任何两个环节之间：</p><ul><li>钱已经扣了，但你没收到数据；</li><li>请求已经发给上游，但上游正在处理，还没返回；</li><li>交易已广播，但你查不到它是否上链。</li></ul><p>在这几种情况下，<strong>&quot;没收到响应&quot;对应的真实状态完全不同</strong>，用一个&quot;失败&quot;概括它们，必然会出错。</p><h2 id="常见的几种处理方式-为什么不行" tabindex="-1">常见的几种处理方式，为什么不行 <a class="header-anchor" href="#常见的几种处理方式-为什么不行" aria-label="Permalink to &quot;常见的几种处理方式，为什么不行&quot;">​</a></h2><h3 id="方式一-超时就当失败-重新签名重试" tabindex="-1">方式一：超时就当失败，重新签名重试 <a class="header-anchor" href="#方式一-超时就当失败-重新签名重试" aria-label="Permalink to &quot;方式一：超时就当失败，重新签名重试&quot;">​</a></h3><p>这正是上面的故事。每次重新签名都是一份新的授权，新授权会产生新的扣款。</p><h3 id="方式二-超时就当成功" tabindex="-1">方式二：超时就当成功 <a class="header-anchor" href="#方式二-超时就当成功" aria-label="Permalink to &quot;方式二：超时就当成功&quot;">​</a></h3><p>反过来也不对。如果请求其实根本没有送达，买方付了钱却什么都没拿到。</p><h3 id="方式三-超时后立刻释放预算" tabindex="-1">方式三：超时后立刻释放预算 <a class="header-anchor" href="#方式三-超时后立刻释放预算" aria-label="Permalink to &quot;方式三：超时后立刻释放预算&quot;">​</a></h3><p>假设客户端为这次付款预留了额度。签名一旦发出，这份授权在到期前<strong>仍然可能被卖方或清算方提交上链</strong>。如果此时把预算释放掉，同一笔钱就可能被再花一次：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>预留 0.1 → 签名发出 → 超时 → 立刻释放预算 → Agent 再花 0.1</span></span>
<span class="line"><span>                                             ↑</span></span>
<span class="line"><span>                      原来那份签名随后被提交上链，实际支出 0.2</span></span></code></pre></div><h3 id="方式四-无限重试直到成功" tabindex="-1">方式四：无限重试直到成功 <a class="header-anchor" href="#方式四-无限重试直到成功" aria-label="Permalink to &quot;方式四：无限重试直到成功&quot;">​</a></h3><p>没有节制的重试，在对方真的故障时会演变成重试风暴，同时放大上面所有风险。</p><h2 id="agentpay-的做法" tabindex="-1">AgentPay 的做法 <a class="header-anchor" href="#agentpay-的做法" aria-label="Permalink to &quot;AgentPay 的做法&quot;">​</a></h2><p>核心思路只有一句话：<strong>把&quot;结果不确定&quot;当作一个明确的状态，而不是错误。</strong> 处于这个状态时，系统只允许&quot;查询&quot;和&quot;等待&quot;，不允许&quot;再付一次&quot;。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>          超时 / 异常</span></span>
<span class="line"><span>              │</span></span>
<span class="line"><span>              ▼</span></span>
<span class="line"><span>       结果未知（明确状态）</span></span>
<span class="line"><span>              │</span></span>
<span class="line"><span>     ┌────────┴────────┐</span></span>
<span class="line"><span>     ▼                 ▼</span></span>
<span class="line"><span>  查询真实状态        不允许盲目重试</span></span>
<span class="line"><span>     │</span></span>
<span class="line"><span> ┌───┼─────────┐</span></span>
<span class="line"><span> ▼   ▼         ▼</span></span>
<span class="line"><span>已完成 确认未发生  仍无法判断</span></span>
<span class="line"><span> │    │         │</span></span>
<span class="line"><span>继续  安全释放   保持锁定，</span></span>
<span class="line"><span>      预算      转人工核查</span></span></code></pre></div><p>具体来说，有四条规则。</p><p><strong>1. 签名发出后，预算不会因为网络问题被立即释放。</strong> 必须同时满足两个条件才会释放：授权已经过期（含一小段安全余量），并且确认它没有被结算。在此之前，这份预算保持占用。</p><p><strong>2. 结果未知时，禁止盲目重新提交。</strong> 如果结算处于结果未知状态，系统只做状态查询和对账，<strong>不会再次提交支付</strong>。</p><p><strong>3. 用同一个幂等键重试，不会重复扣费。</strong> 客户端为一次业务请求带上固定的 <code>Idempotency-Key</code>。网关识别到同一个键，会直接复用上一次的结果或已冻结的额度，这被称为&quot;免费重放&quot;。如果同一个键被拿去提交内容不同的请求，则会被拒绝，防止篡改。</p><p><strong>4. 付款成功与服务交付分开记录。</strong> 链上结算成功但上游交付失败时，系统会保留&quot;已付款、待补偿&quot;的记录，并支持免费重试交付，而不是简单地标记成失败。</p><h3 id="平台钱包模式下的处理" tabindex="-1">平台钱包模式下的处理 <a class="header-anchor" href="#平台钱包模式下的处理" aria-label="Permalink to &quot;平台钱包模式下的处理&quot;">​</a></h3><p>使用平台虚拟钱包时，流程是&quot;冻结额度 → 调用上游 → 确认扣款或释放&quot;。不同的上游结果对应不同的处理：</p><table tabindex="0"><thead><tr><th>上游返回</th><th>处理</th></tr></thead><tbody><tr><td>成功（2xx）</td><td>确认扣款</td></tr><tr><td>明确的客户端错误（4xx）</td><td>释放冻结，不扣费</td></tr><tr><td>服务端异常（5xx）或超时</td><td><strong>保持冻结</strong>，既不扣款也不释放，转人工核查</td></tr></tbody></table><p>5xx 和超时不能直接释放，因为上游可能已经执行了一部分，甚至已经执行完毕。保持冻结是最保守的选择：资金暂时不可用，但不会多扣，也不会白送服务。冻结有超时时间，到期后由恢复流程处理。</p><h3 id="客户端该怎么写" tabindex="-1">客户端该怎么写 <a class="header-anchor" href="#客户端该怎么写" aria-label="Permalink to &quot;客户端该怎么写&quot;">​</a></h3><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> httpx</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">headers </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;Authorization&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Bearer </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">api_key</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;Idempotency-Key&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;order-20261020-001&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 同一业务请求固定不变</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">try</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    resp </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> httpx.get(url, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">headers</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">headers, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">timeout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">except</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> httpx.TimeoutException:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 超时后用同一个幂等键重试，不会重复扣费</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    resp </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> httpx.get(url, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">headers</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">headers, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">timeout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>关键点只有一个：<strong>重试时必须复用同一个幂等键。</strong> 每次重试都生成新的键，等于告诉网关&quot;这是一笔新请求&quot;。</p><h2 id="效果-把开头的故事重放一遍" tabindex="-1">效果：把开头的故事重放一遍 <a class="header-anchor" href="#效果-把开头的故事重放一遍" aria-label="Permalink to &quot;效果：把开头的故事重放一遍&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Agent 付款并请求，卖方成功收款</span></span>
<span class="line"><span>2. 响应丢失，Agent 收到超时</span></span>
<span class="line"><span>3. Agent 带着同一个幂等键重试</span></span>
<span class="line"><span>4. 网关识别为同一笔请求 → 返回已有结果，不再扣款</span></span></code></pre></div><p>最终只扣一次，数据也拿到了。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q：为什么不让系统等久一点，直接拿到明确结果？</strong> 网络和链上的确认时间不可控，无限等待会拖垮 Agent。所以做法是：先返回&quot;处理中或结果未知&quot;，再由后台对账补全最终状态。</p><p><strong>Q：幂等键应该怎么生成？</strong> 用业务上能唯一标识&quot;这一次意图&quot;的值，例如任务 ID 加步骤编号。同一个业务动作的所有重试用同一个键，不同的业务动作用不同的键。</p><p><strong>Q：保持冻结会不会一直占用资金？</strong> 不会一直占用。冻结有超时时间，到期后由恢复流程处理；需要人工判断的，也会在控制台里标记出来。</p><p><strong>Q：这能保证绝对不会重复扣款吗？</strong> 这些规则大幅降低了风险，并有故障注入测试覆盖（上游 5xx、网络中断、进程崩溃）。但项目仍处于实验阶段，未经过独立安全审计，不应作为&quot;绝对保证&quot;来依赖。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>想理解&quot;并发下预算为什么要原子预留&quot;：<a href="./budget-reservation">预算预留</a></li><li>想理解&quot;付款、结算、交付为什么要分开记录&quot;：<a href="./three-state-model">三态模型</a></li><li>想看到故障时的实际表现：<a href="./../05-hands-on/read-payment-trace">读懂一笔支付的全链路</a></li></ul><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><ul><li><a href="/docs/specs/state-machine">统一支付状态机</a>：各环节的状态迁移与恢复流程</li><li><a href="/docs/specs/protocol-consistency">协议一致性契约</a>：幂等键与错误码约定</li><li><a href="/docs/specs/wallet-ledger">钱包与账本规范</a>：冻结、确认、释放的完整规则</li><li><a href="/docs/specs/threat-model-v1">威胁模型 v1</a>：冻结泄漏与重复支付相关威胁</li></ul>`,55)])])}const g=a(e,[["render",p]]);export{c as __pageData,g as default};
